#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i=0;i<10;i++) cin >> a[i];

    vector<vector<int>> adj(n+1);
    vector<unordered_set<int>> adj_set(n+1);
    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        adj_set[u].insert(v);
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count(); };

    mt19937 rng(12345);

    vector<int> best_path;

    while(elapsed_ms() < 3800){
        int sv = rng() % n + 1;

        vector<int> path;
        vector<bool> used(n+1, false);
        vector<int> pos(n+1, -1); // position in path
        path.push_back(sv);
        used[sv] = true;
        pos[sv] = 0;

        auto rebuild_pos = [&](){
            for(int i=0;i<(int)path.size();i++) pos[path[i]] = i;
        };

        // Try to extend from back
        auto extend_back = [&]() -> bool {
            int cur = path.back();
            int best = -1, best_deg = INT_MAX;
            for(int v : adj[cur]){
                if(used[v]) continue;
                int deg = (int)adj[v].size();
                if(deg < best_deg || (deg == best_deg && (rng()&1))){
                    best_deg = deg; best = v;
                }
            }
            if(best == -1) return false;
            pos[best] = (int)path.size();
            path.push_back(best);
            used[best] = true;
            return true;
        };

        while(extend_back());

        // Rotation-extension
        for(int iter = 0; iter < 5000 && (int)path.size() < n && elapsed_ms() < 3800; iter++){
            int tail = path.back();
            // Find a node in path that tail connects to
            vector<int> cands;
            for(int v : adj[tail]){
                if(used[v] && pos[v] >= 0 && pos[v] + 1 < (int)path.size()){
                    cands.push_back(pos[v]);
                }
            }
            if(cands.empty()){
                // Random truncation
                int cut = rng() % max(1, (int)path.size()/3) + 1;
                for(int i=0;i<cut && path.size()>1;i++){
                    int b = path.back();
                    used[b]=false; pos[b]=-1;
                    path.pop_back();
                }
                while(extend_back());
                continue;
            }
            int ci = cands[rng() % cands.size()];
            // Reverse path[ci+1..end], so tail connects to path[ci], and path[ci+1] becomes new tail
            reverse(path.begin()+ci+1, path.end());
            rebuild_pos();
            // Now try extending from new tail
            while(extend_back());
        }

        if((int)path.size() > (int)best_path.size()){
            best_path = path;
            if((int)best_path.size() == n) break;
        }
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
}
